from __future__ import annotations

from true_rl_agent.candidates.components import RewardInputs, RewardTerm, TrainingComponents


def stance_margin(inp: RewardInputs):
    return inp.base_height - 0.5 * (inp.roll * inp.roll + inp.pitch * inp.pitch)


def build_training_components() -> TrainingComponents:
    return TrainingComponents(
        name="stance_margin_candidate",
        reward_terms=[RewardTerm(name="stance_margin", weight=1.0, fn=stance_margin)],
        diagnostics=[],
        schedules=[],
        rationale="Add a public reward callable over RewardInputs.",
    )
